-- Access QueryDef: ra_aTtl_q
-- Type: 0

SELECT ra_aTtl.ratSender, ra_aTtl.ratPeriod, ra_aTtl.ratArrived, ra_aTtl.ratArrivedDB, IIf(IsNull([ra_aTtl]![ratArrived]),0,[ra_aTtl]![ratArrived])-IIf(IsNull([ra_aTtl]![ratArrivedDB]),0,[ra_aTtl]![ratArrivedDB]) AS ratArrivedCmpr, ra_aTtl.ratReturned, ra_aTtl.ratReturnedDB, IIf(IsNull([ra_aTtl]![ratReturned]),0,[ra_aTtl]![ratReturned])-IIf(IsNull([ra_aTtl]![ratReturnedDB]),0,[ra_aTtl]![ratReturnedDB]) AS ratReturnedCmpr, ra_aTtl.ratSended, ra_aTtl.ratSendedDB, IIf(IsNull([ratSended]),0,[ratSended])-IIf(IsNull([ratSendedDB]),0,[ratSendedDB]) AS ratSendedCmpr, ra_aTtl.ratInProcess, ra_aTtl.ratInProcessDB, IIf(IsNull([ratInProcess]),0,[ratInProcess])-IIf(IsNull([ratInProcessDB]),0,[ratInProcessDB]) AS ratInProcessCmpr, ra_aTtl.ratWithWork, ra_aTtl.ratWithWorkDB, IIf(IsNull([ratWithWork]),0,[ratWithWork])-IIf(IsNull([ratWithWorkDB]),0,[ratWithWorkDB]) AS ratWithWorkCmpr, ra_aTtl.mTtl, ra_aTtl.mTtlDB, IIf(IsNull([mTtl]),0,[mTtl])-IIf(IsNull([mTtlDB]),0,[mTtlDB]) AS mTtlCmpr, ra_aTtl.mWork, ra_aTtl.mWorkDB, [mWork]-[mWorkDB] AS mWorkCmpr, ra_aTtl.mEquip, ra_aTtl.mEquipDB, [mEquip]-[mEquipDB] AS mEquipCmpr, ra_aTtl.mOthers, ra_aTtl.mOthersDB, [mOthers]-[mOthersDB] AS mOthersCmpr, ra_aTtl.aTtl, ra_aTtl.aTtlDB, [aTtl]-[aTtlDB] AS aTtlCmpr, ra_aTtl.aWork, ra_aTtl.aWorkDB, [aWork]-[aWorkDB] AS aWorkCmpr, ra_aTtl.aEquip, ra_aTtl.aEquipDB, [aEquip]-[aEquipDB] AS aEquipCmpr, ra_aTtl.aOthers, ra_aTtl.aOthersDB, [aOthers]-[aOthersDB] AS aOthersCmpr, ra_aTtl.dTtl, ra_aTtl.dTtlDB, [dTtl]-[dTtlDB] AS dTtlCmpr, ra_aTtl.dWork, ra_aTtl.dWorkDB, [dWork]-[dWorkDB] AS dWorkCmpr, ra_aTtl.dEquip, ra_aTtl.dEquipDB, [dEquip]-[dEquipDB] AS dEquipCmpr, ra_aTtl.dOthers, ra_aTtl.dOthersDB, [dOthers]-[dOthersDB] AS dOthersCmpr, IIf((Abs([ratArrivedCmpr])+Abs([ratReturnedCmpr])+Abs([ratSendedCmpr])+Abs([ratInProcessCmpr])+Abs([ratWithWorkCmpr])+Abs([mTtlCmpr])+Abs([mWorkCmpr])+Abs([mEquipCmpr])+Abs([mOthersCmpr])+Abs([aTtlCmpr])+Abs([aWorkCmpr])+Abs([aEquipCmpr])+Abs([aOthersCmpr])+Abs([dTtlCmpr])+Abs([dWorkCmpr])+Abs([dEquipCmpr])+Abs([dOthersCmpr]))=0,"совпадение","не совпадение") AS CmprRslt
FROM ra_aTtl
ORDER BY ra_aTtl.ratSender, ra_aTtl.ratPeriod;
